"""Printable operating draft and blank report annexes generated from the versioned catalog."""
from html import escape
from backend.organization_catalog import POSITIONS, STRUCTURE_NOTES
from backend.sop_catalog import CATALOG, CATALOG_VERSION
from backend.constants import ROLE_LABELS


def role_names(roles):
    return ', '.join(ROLE_LABELS.get(r,r) for r in roles)


STAGE_NAMES={'submitted':'Diajukan','assigned':'Menunggu penerimaan','rejected':'Ditolak',
             'accepted':'Diterima Lab','design':'Desain','production':'Produksi','finishing':'Finishing',
             'rework':'Perbaikan','qc_pending':'Menunggu QC','ready':'Siap diserahkan','completed':'Selesai'}


def manual_html():
    e=escape
    positions={p[0]:p for p in POSITIONS}
    hierarchy=''.join('<tr><td>'+e(name)+'</td><td>'+e(division)+'</td><td>'+e(positions[parent][1] if parent else '—')+'</td></tr>' for code,name,parent,division,roles in POSITIONS)
    sections=[]
    for s in CATALOG:
        items=''.join('<tr><td>□ Sesuai<br>□ Temuan'+('<br>□ N/A + alasan' if i['allow_na'] else '')+'</td><td>'+e(i['key'])+'<br>'+e(i['text'])+('<br><b>Bukti wajib dilampirkan</b>' if i['evidence_required'] else '')+'</td><td>Catatan: __________________<br>Tindakan: _________________<br>PJ / Tenggat: ______________</td></tr>' for i in s['items'])
        sections.append('<section class="sop"><div class="kicker">'+e(s['division'])+' · '+e(s['code'])+' · '+e(s['version'])+'</div><h2>'+e(s['title'])+'</h2><p>'+e(s['purpose'])+'</p><dl><dt>Pelaksana</dt><dd>'+e(role_names(s['roles']))+'</dd><dt>Peninjau</dt><dd>'+e(role_names(s['reviewers']))+' (orang berbeda)</dd><dt>Frekuensi</dt><dd>'+e(s['frequency'])+'</dd><dt>Konteks</dt><dd>'+('Wajib order dalam penugasan; tahap: '+e(', '.join(STAGE_NAMES.get(x,x) for x in s['allowed_states']) or 'sesuai akses order') if s['order_policy']=='required' else 'Administratif; tidak menyertakan rincian medis')+'</dd></dl><table><thead><tr><th>Hasil</th><th>Pemeriksaan</th><th>Temuan / tindak lanjut</th></tr></thead><tbody>'+items+'</tbody></table><h3>Lampiran yang disiapkan</h3><ul>'+''.join('<li>'+e(x)+'</li>' for x in s['evidence_examples'])+'</ul><p class="note">Gunakan hasil pemeriksaan aktual. “Ada temuan” memerlukan uraian, rencana tindakan, penanggung jawab, dan tenggat. Bukti wajib harus ditautkan ke item yang bersangkutan.</p></section>')
    return '''<!doctype html><html lang="id"><meta charset="utf-8"><title>NAM — Draf SOP dan Lampiran Laporan</title><style>
    @page{size:A4;margin:18mm}*{box-sizing:border-box}body{font:13px/1.6 "Segoe UI",Arial,sans-serif;color:#293c33;background:#eeefe8;margin:0}main{max-width:1050px;background:white;margin:auto;padding:60px}h1,h2{font-family:Georgia,serif;font-weight:normal}h1{font-size:46px;line-height:1.2;margin:24px 0}h2{font-size:28px;line-height:1.25}h3{font-size:15px}.kicker{font-size:11px;letter-spacing:2px;color:#8d7348;text-transform:uppercase}.cover{padding:35px 0 90px;border-bottom:2px solid #ad8b56}.note{padding:12px;background:#f5f3eb;border-left:3px solid #ad8b56;font-size:12px}.sop{padding-top:45px;break-before:page}table{width:100%;border-collapse:collapse;margin:22px 0}td,th{border:1px solid #d7ddd1;padding:10px;text-align:left;vertical-align:top;font-size:12px}th{background:#edf0e7;color:#2f4f40}tr{break-inside:avoid}dl{display:grid;grid-template-columns:100px 1fr;gap:6px}dt{font-weight:bold}dd{margin:0}.line{border-bottom:1px solid #afb7a8;min-height:32px}a{color:#356048}.toc li{margin:5px 0}@media print{body{background:white}main{padding:0;max-width:none}.cover{padding-top:40px;min-height:230mm}.sop{padding-top:0}h2,h3{break-after:avoid}.note{break-inside:avoid}} </style><body><main><section class="cover"><div class="kicker">Naraya Aurentis Monolithic · NAM DMS</div><h1>Draf SOP operasional<br>&amp; lampiran laporan.</h1><p>Klinik · Laboratorium · FAT · Operasional · Divisi pendukung</p><p>Versi '''+e(CATALOG_VERSION)+''' · 20 Oktober 2026<br>Untuk latihan lokal dengan data sintetis.</p><div class="note">Dokumen kerja untuk ditelaah dan disahkan pemilik proses. Tidak memuat protokol tindakan medis, pengesahan hukum, atau izin go-live. Checklist laporan tidak menjalankan persetujuan klinis, QC, pembayaran, atau perubahan janji.</div><p>Penyusun: __________________<br>Penelaah operasional: __________________<br>Penelaah klinis / FAT sesuai lingkup: __________________<br>Tanggal pengesahan: __________________</p></section><section class="sop"><h2>Cara menggunakan</h2><ol><li>Pilih SOP sesuai peran dan pekerjaan yang benar-benar dilakukan.</li><li>Untuk laporan berorder, pilih order dalam penugasan dan tahap workflow yang sesuai.</li><li>Isi setiap pemeriksaan: Sesuai, Ada temuan, atau Tidak relevan hanya jika diizinkan.</li><li>Catat uraian temuan, tindakan, pemilik, dan tenggat. Tidak relevan memerlukan alasan.</li><li>Lampirkan bukti fiktif ke item checklist; jangan mengunggah data pasien asli.</li><li>Simpan draf, periksa ulang, lalu ajukan kepada petugas lain yang berwenang.</li><li>Jika dikembalikan, perbaiki dan ajukan ulang. Pengajuan lama dan bukti sebelumnya tetap tersimpan.</li><li>Unduh ZIP berisi laporan cetak, lampiran, dan riwayat. Buka laporan.html setelah ZIP diekstrak.</li></ol><p>Format bukti: PDF tanpa fitur aktif, PNG, JPG, TXT. Maksimal 3 MB/berkas, 8 lampiran dan total 15 MB aktif/laporan. Unduhan dibatasi sesuai izin. Validasi format demo belum menggantikan pemindaian malware dan penyimpanan terenkripsi.</p><h3>Pemisahan kewenangan</h3><ul><li>Resepsionis tidak mengubah diagnosis, meluluskan QC, memverifikasi penerimaan sendiri, atau menghapus piutang.</li><li>Dokter berwenang atas keputusan klinis. Lab bertanggung jawab atas progres dan komunikasi setelah penerimaan.</li><li>Klinik mitra menjadi penerima utama order eksternal; kontak langsung ke pasien eksternal belum diaktifkan.</li><li>Pesan dibaca tidak berarti menyetujui tanggal baru; tanggal semula dipertahankan.</li><li>FAT tidak menganggap screenshot sebagai settlement. Verifikasi pada aplikasi tetap manual demo.</li><li>IT dan atasan tidak mendapatkan hak membaca medis karena jabatan.</li><li>Peninjauan laporan hanya menyatakan laporan telah ditelaah. Jika pemeriksa berwenang belum tersedia, laporan tetap menunggu.</li></ul></section><section class="sop"><h2>Struktur dan pemetaan jabatan</h2><p>Bagan pengguna menjadi acuan. Nama pribadi belum ditranskripsi. Akun latihan adalah pemetaan fungsi, bukan pengangkatan pegawai.</p><table><tr><th>Jabatan</th><th>Divisi</th><th>Melapor ke (draf)</th></tr>'''+hierarchy+'</table><ul>'+''.join('<li>'+e(n)+'</li>' for n in STRUCTURE_NOTES)+'</ul></section><section class="sop"><h2>Daftar prosedur</h2><ol class="toc">'+''.join('<li>'+e(s['code']+' — '+s['title'])+'</li>' for s in CATALOG)+'</ol></section>'+''.join(sections)+'''
    <section class="sop"><div class="kicker">Lampiran A</div><h2>Form laporan pemeriksaan</h2><p>Nomor: __________ SOP / Versi: __________ Revisi: _______<br>Tanggal / Shift: __________ Unit: __________<br>Penyusun / Jabatan: __________________________<br>Order / Referensi administratif: __________________________</p><h3>Ringkasan hasil</h3><div class="line"></div><div class="line"></div><h3>Temuan dan tindak lanjut</h3><table><tr><th>Item / Temuan</th><th>Tindakan / Prioritas</th><th>Penanggung jawab</th><th>Tenggat / Status</th></tr>'''+('<tr><td>&nbsp;<br>&nbsp;</td><td></td><td></td><td></td></tr>'*4)+'''</table><p>Peninjau berbeda dari penyusun: __________________<br>Hasil: □ Ditinjau □ Dikembalikan untuk perbaikan<br>Catatan: __________________________________________</p></section>
    <section class="sop"><div class="kicker">Lampiran B</div><h2>Register bukti laporan</h2><table><tr><th>Nomor / Item SOP</th><th>Nama berkas / Versi</th><th>Isi bukti (tanpa data pribadi)</th><th>Pengunggah / Waktu / SHA-256</th></tr>'''+('<tr><td>&nbsp;<br>&nbsp;</td><td></td><td></td><td></td></tr>'*6)+'''</table><p>Asal bukti: □ Dokumen latihan □ Foto model latihan □ Rekap anonim<br>Pemeriksaan: □ Tidak ada data pasien asli □ Sesuai item □ Berkas dapat dibaca<br>Riwayat penggantian: __________________________________</p><h3>Lampiran C — Serah terima</h3><p>Waktu: __________ Pengirim: __________ Penerima berwenang: __________<br>Referensi / kelengkapan: __________________________________<br>Kondisi diterima / ketidaksesuaian: __________________________<br>Tindak lanjut dan tenggat: __________________________________</p><h3>Lampiran D — Kendali revisi</h3><table><tr><th>Versi</th><th>Alasan / Bagian berubah</th><th>Penyusun / Peninjau</th><th>Tanggal</th></tr>'''+('<tr><td>&nbsp;<br>&nbsp;</td><td></td><td></td><td></td></tr>'*3)+'''</table></section></main></body></html>'''


def manual_markdown():
    lines=['# NAM DMS — Draf SOP, checklist dan lampiran laporan', '',f'Versi {CATALOG_VERSION} · 20 Oktober 2026 · demo lokal / data fiktif.',
           'Belum disahkan. Tidak mengganti protokol klinis, QC, verifikasi pembayaran atau persetujuan pasien.',
           '', '## Cara memakai', 'Pilih SOP → isi hasil aktual → catat temuan/tindakan/PJ/tenggat → unggah bukti ke item → ajukan → ditinjau petugas lain atau dikembalikan. Riwayat dipertahankan.',
           'Bukti: PDF, PNG, JPG, TXT; 3 MB per berkas, 8 berkas / 15 MB aktif per laporan.', '']
    for s in CATALOG:
        lines.extend([f"## {s['code']} — {s['title']}",s['purpose'],f"Pelaksana: {role_names(s['roles'])}. Peninjau (orang berbeda): {role_names(s['reviewers'])}.",f"Frekuensi: {s['frequency']}. Konteks order: {s['order_policy']}.",''])
        for i in s['items']:lines.append(f"- [ ] {i['key']}: {i['text']}"+(' **Bukti wajib.**' if i['evidence_required'] else '')+(' N/A boleh dengan alasan.' if i['allow_na'] else ''))
        lines.extend(['','Lampiran: '+ '; '.join(s['evidence_examples']), 'Hasil setiap item: Sesuai / Ada temuan / N/A jika diperbolehkan. Temuan: uraian, tindakan, PJ, tenggat.',''])
    lines.extend(['## Lampiran A — Form laporan','Nomor | SOP / Versi | Tanggal / Shift | Unit | Penyusun / Jabatan | Order/Referensi | Ringkasan | Peninjau / Catatan','',
                  '## Lampiran B — Register bukti','Item SOP | Nama berkas / Versi | Isi bukti | Pengunggah / Waktu | SHA-256','',
                  '## Lampiran C — Serah terima','Waktu | Pengirim | Penerima berwenang | Referensi | Kelengkapan / kondisi | Tindak lanjut / tenggat','',
                  '## Lampiran D — Kendali revisi','Versi | Alasan / Bagian berubah | Penyusun | Peninjau | Tanggal'])
    return '\n'.join(lines)+'\n'
